layouts.css:
.aha-header-section-hero-pink{
  --aha-header-section-hero-pink-surface:var(--aha-vivid-pink-100);
  --aha-header-section-hero-pink-ink:var(--aha-text-inverse);
  container:aha-header-section-hero-pink / inline-size;
  position:relative;isolation:isolate;overflow:hidden;
  font-family:var(--aha-font-product);
  background:var(--aha-white);
}
.aha-header-section-hero-pink--pale{
  --aha-header-section-hero-pink-surface:var(--aha-vivid-pink-5);
  --aha-header-section-hero-pink-ink:var(--aha-text-default);
}
.aha-header-section-hero-pink *{box-sizing:border-box}
:where(.aha-header-section-hero-pink) h1,:where(.aha-header-section-hero-pink) p{margin:0}
.aha-header-section-hero-pink__surface{position:absolute;inset:0;z-index:-1;overflow:hidden;background:var(--aha-header-section-hero-pink-surface)}
.aha-header-section-hero-pink__inner{
  display:flex;flex-direction:row;align-items:center;justify-content:space-between;gap:var(--aha-space-64);
  width:100%;max-width:1280px;margin:0 auto;
  padding:var(--aha-space-64);
}
.aha-header-section-hero-pink__copy{display:flex;flex-direction:column;align-items:flex-start;width:100%;max-width:720px;color:var(--aha-header-section-hero-pink-ink)}
.aha-header-section-hero-pink__title{
  margin-bottom:var(--aha-space-24);
  font-size:var(--aha-size-h1);font-weight:var(--aha-weight-semibold);line-height:var(--aha-line-height-heading);
  letter-spacing:var(--aha-letter-spacing-headlines);
  color:var(--aha-header-section-hero-pink-ink);
}
.aha-header-section-hero-pink__text{
  margin-bottom:var(--aha-space-32);
  font-size:var(--aha-size-l);font-weight:var(--aha-weight-regular);line-height:var(--aha-line-height-body);
  letter-spacing:var(--aha-letter-spacing-paragraph);
  color:var(--aha-header-section-hero-pink-ink);
}
.aha-header-section-hero-pink__media{width:100%;max-width:680px}
.aha-header-section-hero-pink__image{
  display:block;width:100%;aspect-ratio:4 / 3;object-fit:cover;
  border-radius:var(--aha-radius-xl);background:var(--aha-bg-container-secondary);
}
.aha-header-section-hero-pink--vertical .aha-header-section-hero-pink__inner{flex-direction:column;justify-content:flex-start;gap:var(--aha-space-48)}
.aha-header-section-hero-pink--vertical .aha-header-section-hero-pink__copy{align-items:center;text-align:center}
.aha-header-section-hero-pink--vertical .aha-header-section-hero-pink__media{max-width:960px}
.aha-header-section-hero-pink--vertical .aha-header-section-hero-pink__image{aspect-ratio:16 / 9}
@container aha-header-section-hero-pink (max-width:991px){
  .aha-header-section-hero-pink__inner{flex-direction:column;align-items:flex-start;justify-content:flex-start;max-width:728px;gap:var(--aha-space-48)}
  .aha-header-section-hero-pink__title{font-size:var(--aha-size-h3)}
  .aha-header-section-hero-pink__media,.aha-header-section-hero-pink--vertical .aha-header-section-hero-pink__media{max-width:none}
  .aha-header-section-hero-pink--vertical .aha-header-section-hero-pink__inner{align-items:center}
}
@container aha-header-section-hero-pink (max-width:767px){
  .aha-header-section-hero-pink__inner{--aha-web-gutter:var(--aha-space-24);padding-inline:var(--aha-web-gutter)}
}
@container aha-header-section-hero-pink (max-width:479px){
  .aha-header-section-hero-pink__inner{--aha-web-gutter:var(--aha-space-16);padding:var(--aha-space-32) var(--aha-web-gutter) var(--aha-space-64);gap:var(--aha-space-32)}
  .aha-header-section-hero-pink__text{margin-bottom:var(--aha-space-24)}
  .aha-header-section-hero-pink__title{font-size:var(--aha-size-h4)}
}
.aha-header-section-hero-pink__splash{display:none}
.aha-header-section-hero-pink:not(.aha-header-section-hero-pink--pale) .aha-header-section-hero-pink__splash{display:block;position:absolute;inset:0;z-index:0;overflow:hidden;container-type:size;pointer-events:none;border-radius:inherit;--aha-header-section-hero-pink-splash-width:calc(4.5*min(100cqw,100cqh)*sqrt(max(1,tan(atan2(100cqw,100cqh))*9/16,9/16/tan(atan2(100cqw,100cqh)))))}
.aha-header-section-hero-pink__splash-icon{position:absolute;display:block;max-width:none;height:auto;width:var(--aha-header-section-hero-pink-splash-width);left:calc(var(--aha-header-section-hero-pink-splash-across)*100cqw - var(--aha-header-section-hero-pink-splash-width)*0.516209);top:calc(55cqh - var(--aha-header-section-hero-pink-splash-width)*0.418953)}
.aha-header-section-hero-pink__splash{--aha-header-section-hero-pink-splash-across:.75}

